// Styles
import "react-loader-spinner/dist/loader/css/react-spinner-loader.css";
import "react-datepicker/dist/react-datepicker.css";
import "react-dates/initialize";
import "react-dates/lib/css/_datepicker.css";

import React, { useState, useEffect } from "react";
import { FormattedMessage } from "react-intl";
import { SingleDatePicker } from "react-dates";
import Loader from "react-loader-spinner";
import moment from "moment";
import Select from "react-select";
import { useHistory } from "react-router-dom";

// Redux
import { connect } from "react-redux";
import { fetchInterAffiliateSummSettlement, downloadInterAffiliateSummSettlement } from "../../../../actions/filesets";
import { fetchAffiliatesNamesAndCodes, getRegionCodes } from "../../../../actions/affiliates";
import { closeAlert } from "../../../../actions/utils";

// Components
import { Alert, Button, Card, CardBody, CardHeader, Col, Row, Table as Table2 } from "reactstrap";
import ErrorMessage from "../../../../components/ErrorMessage";

// query string
const queryString = require("query-string");

const SumSettlement = ({
	// function props
	closeAlert,
	getRegionCodes,
	downloadInterAffiliateSummSettlement,
	fetchAffiliatesNamesAndCodes,
	fetchInterAffiliateSummSettlement,
	// query string props
	location                             : { search: queryParams }, // gets the query string from props.search and save it as queryParams
	// state variables props
	alertError,
	download_status,
	regionCodes,
	allAffiliates,
	interAffiliateSumSettlement,
	interAffiliateSumSettlementError,
}) => {
	// QUERY STRING VARIABLES
	let { settlementDate } = queryString.parse(queryParams);
	let regionCode = queryString.parse(queryParams)["region-code"];
	let issuerCode = queryString.parse(queryParams)["issuer-code"];

	const history = useHistory(); // save react router history to history
	const [ focused, setFocused ] = useState(false);

	const [ startDate, setStartDate ] = useState(moment(settlementDate));
	useEffect(
		() => {
			setStartDate(moment(settlementDate));
		},
		[ settlementDate ],
	);

	// React select ony takes objec e.g {label: "USD": value:"USD"} so this construct achieves this but is also dynamic to what ever is passed as the region code in the query string.
	const [ selectedRegion, setSelectedRegion ] = useState({
		label : regionCode,
		value : regionCode,
	});
	useEffect(
		() => {
			// handles selected regionCode update in query string
			setSelectedRegion({
				label : regionCode,
				value : regionCode,
			});
		},
		[ regionCode ],
	);

	// sets selectedIssuer state with the value of issuerCode gotten from the query string above
	const [ selectedIssuer, setselectedIssuer ] = useState({
		label : issuerCode,
		value : issuerCode,
	});

	// updates selectedIssuer as it changes in the questry string
	useEffect(
		() => {
			// handles selected regionCode update in query string
			setselectedIssuer({
				label : issuerCode,
				value : issuerCode,
			});
		},
		[ issuerCode ],
	);

	// Use Effect Handles General Updates
	useEffect(
		() => {
			getRegionCodes();
			fetchAffiliatesNamesAndCodes();
			fetchInterAffiliateSummSettlement(settlementDate, regionCode, issuerCode);
		},
		[ queryParams ],
	);

	const handleSubmitDate = (selectedDate, region, issuer) => {
		let settlementDate = moment(selectedDate).format("YYYY-MM-DD");
		history.push(
			`/interaffiliate/reports/sum-settlement?settlementDate=${settlementDate}&issuer-code=${issuer.value}&region-code=${region.label}`,
		);
	};

	let SelectRegion = [];
	SelectRegion =
		regionCodes &&
		regionCodes.map((region) => {
			return { label: region.code, value: region };
		});

	const onDismiss = () => {
		closeAlert();
	};

	let AllAffiliate = [];
	AllAffiliate = allAffiliates && allAffiliates.filter((aff) => aff.value !== "ALL");

	console.log("SUMM SETTLEMENT PROPS", interAffiliateSumSettlement);

	return (
		<div className='animated fadeIn'>
			{alertError && (
				<Alert color='danger' toggle={onDismiss}>
					{alertError ? alertError : "Error unable to download. Please Check you entries!"}
				</Alert>
			)}
			<Row>
				<Col lg={12}>
					<Card>
						<CardHeader className={"d-flex w-100 justify-content-between align-items-center"}>
							<strong>
								<React.Fragment>
									{settlementDate}
									<FormattedMessage id=' Summ Settlement' defaultMessage=' Summ Settlement' />
								</React.Fragment>
							</strong>

							<div className={"d-flex justify-content-end align-items-center"} style={{ width: "73%" }}>
								<React.Fragment>
									<SingleDatePicker
										showDefaultInputIcon={true}
										date={startDate} // momentPropTypes.momentObj or null
										onDateChange={(startDate) => setStartDate(startDate)} // PropTypes.func.isRequired
										focused={focused} // PropTypes.bool
										onFocusChange={({ focused }) => setFocused(focused)} // PropTypes.func.isRequired
										id='your_unique_id' // PropTypes.string.isRequired,
										isOutsideRange={() => false}
										numberOfMonths={1}
									/>
									<span style={{ width: "14%" }}>
										<Select
											className={"mx-1"}
											onChange={(selectedOption) => setSelectedRegion(selectedOption)}
											value={selectedRegion}
											options={SelectRegion}
										/>
									</span>
									<span style={{ width: "18%" }}>
										<Select
											className={"mx-1"}
											onChange={(selectedOption) => setselectedIssuer(selectedOption)}
											value={selectedIssuer}
											options={AllAffiliate && AllAffiliate}
										/>
									</span>
									<Button
										style={{
											padding                : "9px",
											borderTopLeftRadius    : "0px",
											borderBottomLeftRadius : "0px",
										}}
										className={"btn-sm mx-1"}
										onClick={() => handleSubmitDate(startDate, selectedRegion, selectedIssuer)}
										color='primary'
									>
										{" "}
										<FormattedMessage id='Submit' defaultMessage='Submit' />
									</Button>
								</React.Fragment>

								<React.Fragment>
									<Button
										className={"btn-sm ml-1"}
										style={{ padding: "8px" }}
										color='success'
										onClick={(e) =>
											downloadInterAffiliateSummSettlement(
												settlementDate,
												regionCode,
												issuerCode,
											)}
									>
										<span className={"d-flex px-2 justify-content-center align-items-center"}>
											<i className='fa fa-download' />&nbsp;
											{download_status ? (
												<Loader
													type='ThreeDots'
													color='#FFF'
													height={20}
													width={20}
													style={{ textAlign: "center" }}
												/>
											) : (
												<FormattedMessage id='Download CSV' defaultMessage='Download CSV' />
											)}
										</span>
									</Button>
								</React.Fragment>
							</div>
						</CardHeader>

						<CardBody>
							{/* Handle Loading */}
							{!interAffiliateSumSettlementError &&
							!interAffiliateSumSettlement && (
								<Loader
									type='ThreeDots'
									color='#337AB7'
									height={100}
									width={100}
									style={{ textAlign: "center" }}
								/>
							)}

							{/* Handle unselected fields */}
							{(regionCode === "Region" || issuerCode === "Issuer") &&
							!interAffiliateSumSettlement &&
							interAffiliateSumSettlementError && (
								<ErrorMessage
									message={
										"Please select your region code and Issuer code and click Submit to view entries!"
									}
								/>
							)}

							{/* Handle Errors */}
							{regionCode !== "Region" &&
							issuerCode !== "Issuer" &&
							!interAffiliateSumSettlement &&
							interAffiliateSumSettlementError &&
							interAffiliateSumSettlementError.data && (
								<ErrorMessage message={interAffiliateSumSettlementError.data.message} />
							)}

							{/* Handle display content */}
							{interAffiliateSumSettlement && (
								<React.Fragment>
									{interAffiliateSumSettlement.map((institution, index) => {
										return (
											<Table2
												hover
												bordered
												striped
												responsive
												size='sm'
												style={{ minWidth: "150%" }}
											>
												<thead>
													<h6
														className={"text-primary"}
													>{`INSTITUTION: ${institution.institution}`}</h6>
													<tr key={index}>
														<th>{"Partners"}</th>
														<th>{"Amount Owed To"}</th>
														<th>{"Amount Owed By"}</th>
														<th>{"Fee Owed To"}</th>
														<th>{"Fee Owed By"}</th>
														<th>{"Net Position"}</th>
													</tr>
												</thead>
												<tbody>
													{institution.partners.map((partners, index) => {
														return (
															<React.Fragment>
																<tr key={index}>
																	<td>{partners.name}</td>
																	<td>{partners.amountOwedTo}</td>
																	<td>{partners.amountOwedBy}</td>
																	<td>{partners.interFeeOwedBy}</td>
																	<td>{partners.interFeeOwedTo}</td>
																	<td>{partners.netPositioin}</td>
																</tr>
															</React.Fragment>
														);
													})}
													<tr>
														<td>
															<strong>{institution.totals.name}</strong>
														</td>
														<td>{institution.totals.amountOwedTo}</td>
														<td>{institution.totals.amountOwedBy}</td>
														<td>{institution.totals.feeOwedTo}</td>
														<td>{institution.totals.feeOwedBy}</td>
														<td>{institution.totals.netPosition}</td>
													</tr>
												</tbody>
											</Table2>
										);
									})}

									{/* <tbody> */}
									{/* Did not use full reusable table because of the first <td></td> cant acess this.props from there. */}
									{/* {interAffiliateSumSettlement.map((institution) => {
												return institution.partners.map((partners, index) => {
													return (
														<React.Fragment>
															<tr key={index}>
																<td>{institution.institution}</td>
																<td>{partners.name}</td>
																<td>{partners.amountOwedTo}</td>
																<td>{partners.amountOwedBy}</td>
																<td>{partners.interFeeOwedBy}</td>
																<td>{partners.interFeeOwedTo}</td>
																<td>{partners.netPositioin}</td>
															</tr>
														</React.Fragment>
													);
												}); */}

									{/* })} */}
									{/* </tbody> */}
								</React.Fragment>
							)}
						</CardBody>
					</Card>
				</Col>
			</Row>
		</div>
	);
};

const mapStateToProps = (state) => {
	return {
		alertError                       : state.utils.alertError,
		download_status                  : state.fileSets.download_status,
		interAffiliateSumSettlement      : state.fileSets.interAffiliateSumSettlement,
		interAffiliateSumSettlementError : state.fileSets.interAffiliateSumSettlementError,
		allAffiliates                    : state.affiliates.affiliatesNamesAndCodes,
		regionCodes                      : state.affiliates.region_codes,
	};
};

export default connect(mapStateToProps, {
	closeAlert,
	fetchInterAffiliateSummSettlement,
	fetchAffiliatesNamesAndCodes,
	downloadInterAffiliateSummSettlement,
	getRegionCodes,
})(SumSettlement);
